import React from 'react';
import { useNavigate } from 'react-router-dom';
import { Badge, IconButton } from '../ui';
import { useApp } from '../../data/DataProvider';
import { post } from '../../api/client';
import { dayTime, linkTo, severityTone } from '../../utils';

const GROUPS = [['critical', 'Critical'], ['warning', 'Warning'], ['info', 'Info']];

/** Open alerts generated by the backend rules engine for the selected factory. */
export default function NotificationsPanel({ onClose }) {
  const { alerts, act } = useApp();
  const navigate = useNavigate();

  return (
    <aside className="side-panel w-96 max-w-full">
      <div className="panel-header">
        <div>
          <h3 className="text-sm font-semibold text-fg">Alerts</h3>
          <p className="text-xs text-fg-faint">{alerts.length} open · auto-resolve when the condition clears</p>
        </div>
        <IconButton icon="close" label="Close" plain onClick={onClose} />
      </div>
      <div className="flex-1 overflow-y-auto p-3 space-y-4">
        {GROUPS.map(([sev, label]) => {
          const items = alerts.filter((a) => a.severity === sev);
          if (!items.length) return null;
          return (
            <div key={sev} className="space-y-2">
              <Badge tone={severityTone(sev)} plain>{label.toUpperCase()} ({items.length})</Badge>
              {items.map((a) => (
                <div key={a.id} className={`tile tone-${severityTone(sev)}`}>
                  <button type="button" className="text-left w-full" onClick={() => { navigate(linkTo(a.page, a.entity_type, a.entity_id)); onClose(); }}>
                    <p className="text-xs font-semibold text-fg">{a.title}</p>
                    <p className="text-[11px] text-fg-muted mt-0.5">{a.description}</p>
                    <p className="text-[11px] text-fg mt-1"><b>Action:</b> {a.recommended_action}</p>
                  </button>
                  <div className="flex items-center justify-between mt-2 gap-2">
                    <span className="text-[10px] text-fg-faint">{a.factory} · {a.stage} · {dayTime(a.created_at)}</span>
                    {a.status === 'Acknowledged'
                      ? <span className="text-[10px] text-fg-faint">Acknowledged by {a.acknowledged_by}</span>
                      : <button type="button" className="link-btn" onClick={() => act(() => post(`/api/alerts/${a.id}/ack`), 'Alert acknowledged')}>ACKNOWLEDGE</button>}
                  </div>
                </div>
              ))}
            </div>
          );
        })}
        {alerts.length === 0 && <p className="text-center text-sm text-fg-faint py-8">No open alerts</p>}
      </div>
    </aside>
  );
}
